import{_ as t,o as p,c as o,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Month 2021: Ceph Project Update","description":"","frontmatter":{"title":"Ceph Month 2021: Ceph Project Update","date":"2021-06-01T00:00:00.000Z","updated":"2021-06-02T00:00:00.000Z","tags":["Ceph","分布式存储","软件开发","开源社区","技术更新"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Month_2021_-_Ceph_Project_Update.md","filePath":"posts/2021/Ceph_Month_2021_-_Ceph_Project_Update.md","lastUpdated":1780459816000}'),r={name:"posts/2021/Ceph_Month_2021_-_Ceph_Project_Update.md"};function n(_,e,h,a,l,i){return p(),o("div",null,[...e[0]||(e[0]=[s("<p>本次Ceph Month 2021会议中，Josh和Seth就Ceph项目的最新进展进行了介绍。以下是会议的主要内容和关键要点：</p><ol><li><p><strong>Ceph简介</strong>：Ceph是一个软件定义的存储系统，不依赖特定硬件，可以运行在各种商业组件上，如服务器、网络、硬盘、SSD、VM等。它提供对象、块和文件接口，支持在线扩展和收缩，提供数据耐久性和高可用性。</p></li><li><p><strong>Ceph特性</strong>：Ceph由不可靠的组件构建，具有无单点故障的特点，支持数据复制或纠删码，保证数据安全性。它还提供弹性存储基础设施，集群可以根据需求变化或硬件更新进行扩展。</p></li><li><p><strong>版本和发布</strong>：Ceph每年3月发布稳定版本，提供两个版本的backports（bug修复和安全更新），版本生命周期约为两年。</p></li><li><p><strong>Ceph Month 2021</strong>：会议的目标是更互动和碎片化，避免长时间Zoom会议，分散在几周内，每次几小时，包含计划演讲和非结构化讨论时间。</p></li><li><p><strong>未来计划</strong>：Ceph基金会将举办Cephalocon 2022，地点待定。基金会现有12个职业成员，新加入的有Bloomberg、Cloudbase和Vexos。</p></li><li><p><strong>实验室更新</strong>：Ceph实验室扩展了硬件，改进了测试基础设施，增加了ARM架构支持。</p></li><li><p><strong>遥测数据</strong>：Ceph有遥测模块，用户可以选择分享数据，帮助开发者理解实际问题。</p></li><li><p><strong>未来发展方向</strong>：Ceph将重点关注可靠性、用户体验和适应数据中心及硬件的演进，特别关注Crimson OSD的重新设计和NVMe over Fabrics的支持。</p></li><li><p><strong>后续行动计划</strong>：继续改进Ceph的稳定性和用户体验，扩展测试覆盖和硬件支持，收集社区反馈，为未来的Cephalocon和Ceph发展方向做准备。</p></li></ol><p>本次会议详细介绍了Ceph项目的最新进展，涵盖了特性、版本管理、社区活动、基金会更新、实验室改进、遥测数据以及未来发展方向等关键内容。</p>",3)])])}const d=t(r,[["render",n]]);export{c as __pageData,d as default};
